class Student {
    String name;
    static int grade = 8;

    static void show() {
        System.out.println(grade);              // line 1
        System.out.println(this.name);          // line 2
    }

    void print() {
        System.out.println(grade + " " + name); // line 3
        show();                                 // line 4
    }
}

class Counter {
    static int count;
    int id;

    static {
        count = 10;
        System.out.print("S ");
    }

    Counter() {
        count++;
        id = count;
        System.out.print("C" + id + " ");
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.print("M ");
        Counter a = new Counter();
        Counter b = new Counter();
        System.out.println(a.id + " " + Counter.count);
    }
}
